// src/index.ts
var server = new McpServer({
  name: "Apple Music Mcp",
  version: "1.0.0"
});
var run = (eff) => exports_Effect.runPromise(eff).then((data) => ({
  content: [{
    type: "text",
    text: data === undefined ? "Done" : typeof data === "string" ? data : JSON.stringify(data, null, 2)
  }]
}), (err) => ({ content: [{ type: "text", text: `Error: ${err instanceof Error ? err.message : String(err)}` }] }));
server.registerTool("play", { description: "Play current track in Apple Music" }, () => run(play()));
server.registerTool("pause", { description: "Pause Apple Music" }, () => run(pause()));
server.registerTool("next", { description: "Skip to next track" }, () => run(next()));
server.registerTool("previous", { description: "Go to previous track" }, () => run(prev()));
server.registerTool("volume", {
  description: "Get or set volume (0-100). Omit level to read current volume.",
  inputSchema: exports_external.object({
    level: exports_external.number().optional()
  })
}, ({ level }) => run(volumeTool({ level })));
server.registerTool("songs", {
  description: "List all songs in your Apple Music library",
  inputSchema: exports_external.object({
    limit: exports_external.number().optional(),
    offset: exports_external.number().optional()
  })
}, ({ limit, offset }) => run(songsTool({ limit, offset })));
server.registerTool("playlists", {
  description: "List all playlists in your Apple Music library",
  inputSchema: exports_external.object({
    limit: exports_external.number().optional(),
    offset: exports_external.number().optional()
  })
}, ({ limit, offset }) => run(listPlaylistsTool({ limit, offset })));
server.registerTool("play_playlist", {
  description: "Play a playlist by name",
  inputSchema: exports_external.object({
    name: exports_external.string()
  })
}, ({ name }) => run(playPlaylistTool({ name })));
server.registerTool("play_song", {
  description: "Play a song by name (searches library and plays first match)",
  inputSchema: exports_external.object({
    query: exports_external.string()
  })
}, ({ query }) => run(playTrack(query)));
server.registerTool("tracks", {
  description: "List tracks in a playlist (or current playlist if no name given)",
  inputSchema: exports_external.object({
    name: exports_external.string().optional(),
    limit: exports_external.number().optional(),
    offset: exports_external.number().optional()
  })
}, ({ name, limit, offset }) => run(listTracksTool({ name, limit, offset })));
var main = () => exports_Effect.gen(function* () {
  const transport = new StdioServerTransport;
  yield* exports_Effect.promise(() => server.connect(transport));
});
exports_Effect.runPromise(main());
